setup.csv_summary.py:
"""Summarize a two-column CSV document."""


def totals(document: str) -> dict[str, int]:
    lines = document.splitlines()
    if not lines or lines[0].split(",") != ["name", "amount"]:
        raise ValueError("expected name,amount header")
    result: dict[str, int] = {}
    for line in lines[1:]:
        name, amount = line.split(",")
        result[name] = result.get(name, 0) + int(amount)
    return result

setup.test_csv_summary.py:
import unittest
from csv_summary import totals

class TotalsTests(unittest.TestCase):
    def test_repeated_names(self):
        self.assertEqual(totals('name,amount\nAda,2\nAda,3\n'), {'Ada': 5})
    def test_quoted_comma(self):
        self.assertEqual(totals('name,amount\n"Smith, Ada",7\n'), {'Smith, Ada': 7})
    def test_quoted_newline(self):
        self.assertEqual(totals('name,amount\n"Smith\nAda",7\n'), {'Smith\nAda': 7})
